"""Payment reminders: each reminder goes out at 09:00 in the tenant's time zone on its remind_on date.

schedule_reminder() is called when an invoice is finalized and stores the UTC send time.
"""
from datetime import date, datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo

SEND_AT = time(9, 0)


def send_time_utc(remind_on: date, tz: str, now: datetime) -> datetime:
    """UTC instant for 09:00 local on remind_on."""
    zone = ZoneInfo(tz)
    offset = now.astimezone(zone).utcoffset()          # the tenant's current UTC offset
    local = datetime.combine(remind_on, SEND_AT)
    return (local - offset).replace(tzinfo=timezone.utc)


def schedule_reminder(invoice_id: str, due: date, tz: str, now: datetime, days_before: int = 3) -> dict:
    remind_on = due - timedelta(days=days_before)
    return {"invoice_id": invoice_id, "remind_on": remind_on.isoformat(),
            "send_at_utc": send_time_utc(remind_on, tz, now).isoformat()}

"""Invoice finalization side effects: one webhook per enabled endpoint and one email to the billing contact.

finalize_invoice runs as a Celery task with acks_late=True, so a broker failover can redeliver it.
"""
from dataclasses import dataclass, field


@dataclass
class Outbox:
    events: list = field(default_factory=list)      # stands in for the outbound_events table

    def add(self, invoice_id: str, kind: str, target: str) -> None:
        self.events.append({"invoice_id": invoice_id, "kind": kind, "target": target})


def finalize_invoice(invoice: dict, endpoints: list[str], outbox: Outbox) -> None:
    for url in endpoints:
        outbox.add(invoice["id"], "webhook", url)
    outbox.add(invoice["id"], "email", invoice["billing_email"])

"""Delivers webhooks to tenant-configured URLs and reads the response (streamed, capped at 64 KB) for the audit log."""
import requests

MAX_BODY = 64 * 1024


def deliver(url: str, payload: dict, timeout: float = 10.0) -> dict:
    with requests.post(url, json=payload, timeout=timeout, stream=True) as r:
        body = b""
        for chunk in r.iter_content(chunk_size=8192):
            body += chunk
            if len(body) >= MAX_BODY:
                break
        return {"status": r.status_code, "body": body[:MAX_BODY].decode(errors="replace")}
